import pytest
from fastapi.testclient import TestClient

from app.main import app
from app.engine.calculator import calculate_saju
from app.semantic.tagger import build_semantic_profile
from app.services.content_writer import generate_full_report


client = TestClient(app)


BASE = dict(
    birth_date="1974-02-24",
    birth_location="seoul",
    correction_mode="lmt",
    jasi_boundary=23,
    gender="M",
    target_year=2026,
)


# ---- 엔진 ----
def test_exact_confidence():
    r = calculate_saju(**BASE, birth_time="05:30:00")
    assert r["hour_pillar"] == "庚寅"
    assert r["hour_pillar_confidence"] == "exact"
    assert r["birth_time_mode"] == "exact"


def test_exact_requires_birth_time():
    with pytest.raises(ValueError, match="birth_time"):
        calculate_saju(**BASE, birth_time=None, birth_time_mode="exact")


def test_noon_confidence():
    r = calculate_saju(**BASE, birth_time=None, birth_time_mode="noon")
    assert r["hour_pillar"] is not None
    assert r["hour_pillar_confidence"] == "assumed"
    assert r["birth_time_mode"] == "noon"


def test_noon_rejects_birth_time():
    with pytest.raises(ValueError, match="must be omitted"):
        calculate_saju(**BASE, birth_time="05:30:00", birth_time_mode="noon")


def test_day_only_no_hour_pillar():
    r = calculate_saju(**BASE, birth_time=None, birth_time_mode="day_only")
    assert r["hour_pillar"] is None
    assert r["hour_pillar_confidence"] == "unknown"
    assert r["birth_time_mode"] == "day_only"
    assert r["ten_gods"]["hour_pillar"] is None


def test_day_only_rejects_birth_time():
    with pytest.raises(ValueError, match="must be omitted"):
        calculate_saju(**BASE, birth_time="05:30:00", birth_time_mode="day_only")


def test_invalid_mode_rejected():
    with pytest.raises(ValueError, match="birth_time_mode"):
        calculate_saju(**BASE, birth_time="05:30:00", birth_time_mode="whenever")


# ---- 태거 ----
def test_day_only_pillars_only_three():
    r = calculate_saju(**BASE, birth_time=None, birth_time_mode="day_only")
    profile = build_semantic_profile(r)
    assert "hour_pillar" not in profile["pillars"]
    assert "year_pillar" in profile["pillars"]
    assert "month_pillar" in profile["pillars"]
    assert "day_pillar" in profile["pillars"]
    assert profile["birth_time_mode"] == "day_only"
    assert profile["hour_pillar_confidence"] == "unknown"


def test_day_only_twelve_stages_no_hour():
    r = calculate_saju(**BASE, birth_time=None, birth_time_mode="day_only")
    profile = build_semantic_profile(r)
    assert "hour_pillar" not in profile["structure"]["twelve_stages"]


# ---- 리포트 ----
def test_day_only_chart_layers_three():
    r = calculate_saju(**BASE, birth_time=None, birth_time_mode="day_only")
    profile = build_semantic_profile(r)
    report = generate_full_report(profile, lang="en")
    layers = report["sections"]["chart"]["layers"]
    assert len(layers) == 3
    for layer in layers:
        assert layer["position"] != "hour_pillar"


def test_day_only_meta_marks_mode():
    r = calculate_saju(**BASE, birth_time=None, birth_time_mode="day_only")
    profile = build_semantic_profile(r)
    report = generate_full_report(profile, lang="en")
    assert report["meta"]["schema_version"] == "1.2"
    assert report["meta"]["birth_time_mode"] == "day_only"
    assert report["meta"]["hour_pillar_confidence"] == "unknown"


def test_noon_meta_marks_assumed():
    r = calculate_saju(**BASE, birth_time=None, birth_time_mode="noon")
    profile = build_semantic_profile(r)
    report = generate_full_report(profile, lang="en")
    assert report["meta"]["birth_time_mode"] == "noon"
    assert report["meta"]["hour_pillar_confidence"] == "assumed"
    assert len(report["sections"]["chart"]["layers"]) == 4


# ---- API ----
def test_api_exact_default():
    resp = client.post("/api/v1/saju/calculate", json={
        "birth_date": "1974-02-24",
        "birth_time": "05:30:00",
        "birth_location": "seoul",
        "gender": "M",
        "target_year": 2026,
    })
    assert resp.status_code == 200
    data = resp.json()
    assert data["hour_pillar"] == "庚寅"
    assert data["hour_pillar_confidence"] == "exact"


